import re

_TOKEN_RE = re.compile(r"\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|(\*\*|[-+*/()]))")


def _tokenize(expression):
    tokens = []
    pos = 0
    n = len(expression)
    while pos < n:
        if expression[pos:].strip() == "":
            break
        m = _TOKEN_RE.match(expression, pos)
        if not m:
            raise ValueError("Invalid character at position %d" % pos)
        if m.group(1) is not None:
            try:
                tokens.append(("num", float(m.group(1))))
            except ValueError:
                raise ValueError("Invalid number")
        else:
            tokens.append(("op", m.group(2)))
        pos = m.end()
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        if self.i < len(self.tokens):
            return self.tokens[self.i]
        return None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        self.i += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise ValueError("Empty expression")
        value = self.expr()
        if self.peek() is not None:
            raise ValueError("Unexpected token")
        return value

    def expr(self):
        value = self.term()
        while True:
            tok = self.peek()
            if tok in (("op", "+"), ("op", "-")):
                self.i += 1
                right = self.term()
                value = value + right if tok[1] == "+" else value - right
            else:
                return value

    def term(self):
        value = self.unary()
        while True:
            tok = self.peek()
            if tok in (("op", "*"), ("op", "/")):
                self.i += 1
                right = self.unary()
                if tok[1] == "*":
                    value = value * right
                else:
                    try:
                        value = value / right
                    except ZeroDivisionError:
                        raise ValueError("Division by zero")
            else:
                return value

    def unary(self):
        tok = self.peek()
        if tok in (("op", "-"), ("op", "+")):
            self.i += 1
            operand = self.unary()
            return -operand if tok[1] == "-" else operand
        return self.power()

    def power(self):
        base = self.atom()
        if self.peek() == ("op", "**"):
            self.i += 1
            exp = self.unary()  # right associative, allows unary minus in exponent
            try:
                result = base ** exp
            except ZeroDivisionError:
                raise ValueError("Division by zero")
            except OverflowError:
                raise ValueError("Result too large")
            if isinstance(result, complex):
                raise ValueError("Complex result")
            return result
        return base

    def atom(self):
        kind, val = self.next()
        if kind == "num":
            return val
        if val == "(":
            value = self.expr()
            if self.next() != ("op", ")"):
                raise ValueError("Expected closing parenthesis")
            return value
        raise ValueError("Unexpected token %r" % val)


def evaluate_expression(expression: str) -> float:
    """Evaluate an arithmetic expression such as "2 * (3 + 4) - 1.5" and return the
    result as a float. Numbers, parentheses, unary minus and the operators + - * / **
    are supported. Raise ValueError for malformed input such as "2 +" or an empty string.
    """
    if not isinstance(expression, str):
        raise ValueError("Expression must be a string")
    tokens = _tokenize(expression)
    return float(_Parser(tokens).parse())
